const input = $input.first().json;
const action = String(input.action || '').trim().toLowerCase();
const executionReference = String(input.executionReference || '').trim();
if (!executionReference || executionReference.length > 160) {
  throw new Error('PTS audit requires a valid execution reference');
}

let url;
let body;
if (action === 'start') {
  const organizationId = Number(input.organizationId);
  const accountId = Number(input.accountId);
  const attemptCount = Number(input.attemptCount ?? 1);
  if (![organizationId, accountId, attemptCount].every(Number.isSafeInteger) || attemptCount < 1) {
    throw new Error('PTS audit start identifiers are invalid');
  }
  url = 'https://hsosjnwjangtqtskofag.supabase.co/rest/v1/rpc/start_pts_collection_run';
  body = {
    p_organization_id: organizationId,
    p_integration_account_id: accountId,
    p_workflow_name: String(input.workflowName || '').trim(),
    p_report_type: String(input.reportType || '').trim(),
    p_requested_from_date: input.requestedFromDate || null,
    p_requested_to_date: input.requestedToDate || null,
    p_execution_reference: executionReference,
    p_attempt_count: attemptCount
  };
} else if (action === 'complete') {
  const status = String(input.status || '').trim().toLowerCase();
  const rowsProcessed = Number(input.rowsProcessed ?? 0);
  if (!['succeeded', 'failed'].includes(status) || !Number.isSafeInteger(rowsProcessed) || rowsProcessed < 0) {
    throw new Error('PTS audit completion outcome is invalid');
  }
  url = 'https://hsosjnwjangtqtskofag.supabase.co/rest/v1/rpc/complete_pts_collection_run_by_execution';
  body = {
    p_execution_reference: executionReference,
    p_status: status,
    p_rows_processed: rowsProcessed,
    p_error_category: status === 'succeeded' ? null : String(input.errorCategory || 'unknown').trim().toLowerCase()
  };
} else {
  throw new Error('PTS audit action must be start or complete');
}

return [{ json: { auditAction: action, auditUrl: url, auditBody: body } }];
